#define MAX_BUILDINGS 100
#define EPS 1e-9

typedef struct {
    double x1, y1, x2, y2;
} Building;

int n;
double R;
Building b[MAX_BUILDINGS];

double max(double a, double b) {
    return a > b ? a : b;
}

double min(double a, double b) {
    return a < b ? a : b;
}

int canBlock(double t) {
    double left = -1e18, right = 1e18;
    for (int i = 0; i < n; i++) {
        double y_top = b[i].y2;
        double x_left = b[i].x1;
        double x_right = b[i].x2;
        double need_y = y_top - t;
        if (need_y <= 0) continue;
        double half_width = R / need_y * sqrt(R*R - need_y*need_y);
        if (need_y >= R) {
            half_width = 1e18;
        }
        double cover_left = -half_width;
        double cover_right = half_width;
        left = max(left, cover_left);
        right = min(right, cover_right);
        if (left > right + EPS) return 0;
    }
    return 1;
}

