/*
   Geometry/model used:

   The sun is a disk of radius R whose center moves on a semicircle:
       C(t) = (R cos t, R sin t),  t in [0, pi]
   Sunlight travels vertically downward. Therefore at time t, sunlight is
   completely blocked iff for every x in [Cx-R, Cx+R], there exists some
   building covering that x up to at least height Cy + sqrt(R^2-(x-Cx)^2),
   i.e. the whole solar disk is contained in the union of building silhouettes.

   Each building is an axis-aligned rectangle [x1,x2] x [0,h] (silhouette).
   We compute the upper envelope height H(x) = max h among rectangles covering x.
   Then the sun is blocked iff the disk centered at (Cx,Cy) radius R is fully
   under y = H(x).

   Since H(x) is piecewise constant, with breakpoints at rectangle sides, for
   each interval [a,b] where H(x)=h, the condition over that interval becomes:
       for all x in [a,b] intersect [Cx-R,Cx+R]:
           Cy + sqrt(R^2-(x-Cx)^2) <= h
   The maximum of the left side over the interval occurs at x closest to Cx,
   so equivalently:
       Cy + sqrt(R^2-d^2) <= h
   where d is the distance from Cx to [a,b] (0 if Cx in [a,b]).

   We binary search the last t satisfying the condition.
*/

int main(void) {
    int n;
    double R;

    while (scanf("%lf %d", &R, &n) == 2) {
        if (R < 0 && n < 0) break;

        Rect *rects = (Rect *)malloc(sizeof(Rect) * n);
        double *xs = (double *)malloc(sizeof(double) * (2 * n + 2));

        int m = 0;
        for (int i = 0; i < n; ++i) {
            double x1, y1, x2, y2;
            scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2);
            if (x1 > x2) {
                double t = x1; x1 = x2; x2 = t;
            }
            if (y1 > y2) {
                double t = y1; y1 = y2; y2 = t;
            }
            rects[i].x1 = x1;
            rects[i].x2 = x2;
            rects[i].y1 = y1;
            rects[i].y2 = y2;
            xs[m++] = x1;
            xs[m++] = x2;
        }

        if (n == 0) {
            printf("0.000000\n");
            free(rects);
            free(xs);
            continue;
        }

        qsort(xs, m, sizeof(double), cmp_double);

        double *ux = (double *)malloc(sizeof(double) * (m + 1));
        int k = 0;
        for (int i = 0; i < m; ++i) {
            if (i == 0 || fabs(xs[i] - xs[i - 1]) > EPS) ux[k++] = xs[i];
        }

        int segs = (k > 1 ? k - 1 : 0);
        double *L = (double *)malloc(sizeof(double) * segs);
        double *RR = (double *)malloc(sizeof(double) * segs);
        double *H = (double *)malloc(sizeof(double) * segs);

        for (int i = 0; i < segs; ++i) {
            L[i] = ux[i];
            RR[i] = ux[i + 1];
            double h = 0.0;
            double mid = (L[i] + RR[i]) * 0.5;
            for (int j = 0; j < n; ++j) {
                if (rects[j].x1 <= mid + EPS && mid <= rects[j].x2 + EPS) {
                    if (rects[j].y2 > h) h = rects[j].y2;
                }
            }
            H[i] = h;
        }

        auto int blocked(double t) {
            double cx = R * cos(t);
            double cy = R * sin(t);

            double left = cx - R;
            double right = cx + R;

            for (int i = 0; i < segs; ++i) {
                double a = L[i], b = RR[i];
                if (b <= left + EPS || a >= right - EPS) continue;

                double aa = a > left ? a : left;
                double bb = b < right ? b : right;
                if (aa >= bb - EPS) continue;

                double d;
                if (cx < aa) d = aa - cx;
                else if (cx > bb) d = cx - bb;
                else d = 0.0;

                if (d > R) continue;

                double need = cy + sqrt(fmax(0.0, R * R - d * d));
                if (need > H[i] + 1e-10) return 0;
            }

            /* Also need coverage on any x-range inside [left,right] not covered by any segment */
            double cur = left;
            for (int i = 0; i < segs; ++i) {
                double a = L[i], b = RR[i];
                if (b <= left + EPS || a >= right - EPS) continue;
                double aa = a > left ? a : left;
                double bb = b < right ? b : right;
                if (aa > cur + 1e-10) return 0;
                if (bb > cur) cur = bb;
            }
            if (cur < right - 1e-10) return 0;

            return 1;
        }

        double lo = 0.0, hi = acos(-1.0);
        if (!blocked(0.0)) {
            printf("0.000000\n");
        } else {
            for (int it = 0; it < 100; ++it) {
                double mid = (lo + hi) * 0.5;
                if (blocked(mid)) lo = mid;
                else hi = mid;
            }
            printf("%.6f\n", lo);
        }

        free(rects);
        free(xs);
        free(ux);
        free(L);
        free(RR);
        free(H);
    }

    return 0;
}

