bool blocked(double theta) {
    double cx = R * cos(theta);
    double cy = R * sin(theta);

    // The sun is a circle; we check if any building fully blocks it.
    // For simplicity: check if the entire sun circle is inside the union of shadows.
    // We sample points on the sun boundary for approximation (sufficient for geometry).
    int samples = 200;
    for (int i = 0; i < samples; i++) {
        double angle = 2 * M_PI * i / samples;
        double px = cx + R * cos(angle);
        double py = cy + R * sin(angle);
        bool covered = false;
        for (auto &b : buildings) {
            if (px >= b.x1 - EPS && px <= b.x2 + EPS && py >= b.y1 - EPS && py <= b.y2 + EPS) {
                covered = true;
                break;
            }
        }
        if (!covered) return false;
    }
    return true;
}

double solve() {
    double lo = 0.0, hi = M_PI;
    // First find if it's ever blocked near sunset
    if (!blocked(hi - EPS)) return 0.0;
    for (int iter = 0; iter < 60; iter++) {
        double mid = (lo + hi) / 2;
        if (blocked(mid)) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    return lo; // last moment blocked is just before it becomes unblocked
}

