                } else {
                    hi = mid;
                }
            }
            System.out.printf("%.6f%n", lo);
        }
    }

    static boolean isBlocked(double theta, double r, double[][] rects) {
        double sunX = r * Math.cos(theta);
        double sunY = r * Math.sin(theta);
        List<double[]> intervals = new ArrayList<>();

        for (double[] rect : rects) {
            double x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3];
            // For each vertical edge, compute shadow on ground (y=0)
            double[] xs = {x1, x2};
            for (double x : xs) {
                double[] ys = {y1, y2};
                for (double y : ys) {
                    // Ray from sun to point (x,y) on building
                    double dx = x - sunX;
                    double dy = y - sunY;
                    if (dy >= 0) continue; // point not below sun
                    double t = -sunY / dy;
                    double gx = sunX + t * dx;
                    intervals.add(new double[]{gx, gx});
                }
            }
            // Also consider edges parallel to ground
            // top edge y = y2
            double yTop = y2;
            if (yTop < sunY) {
                double t = -sunY / (yTop - sunY);
                double gx1 = sunX + t * (x1 - sunX);
                double gx2 = sunX + t * (x2 - sunX);
                intervals.add(new double[]{Math.min(gx1, gx2), Math.max(gx1, gx2)});
            }
            // bottom edge y = y1
            double yBot = y1;
            if (yBot < sunY) {
                double t = -sunY / (yBot - sunY);
                double gx1 = sunX + t * (x1 - sunX);
                double gx2 = sunX + t * (x2 - sunX);
                intervals.add(new double[]{Math.min(gx1, gx2), Math.max(gx1, gx2)});
            }
        }

        if (intervals.isEmpty()) return false;
        intervals.sort(Comparator.comparingDouble(a -> a[0]));
        double coverageEnd = intervals.get(0)[0];
        for (double[] interval : intervals) {
            if (interval[0] > coverageEnd + 1e-12) return false;
            coverageEnd = Math.max(coverageEnd, interval[1]);
        }
        return coverageEnd >= 0; // any positive coverage on ground is enough for this angle
    }
}

