/*
 *  The statement as provided is incomplete, but this is the classic geometry task:
 *
 *  - The sun is a circle of radius R whose center moves on a semicircle from left horizon
 *    to right horizon.
 *  - Buildings are axis-aligned rectangles standing on the x-axis, given by [l, r] × [0, h].
 *  - We must output the last time before sunset when the sunlight is still completely blocked.
 *
 *  Standard parametrization:
 *      sun center = (R cos t, R sin t), 0 <= t <= pi
 *  Time increases from sunrise (t = pi) to sunset (t = 0), or vice versa depending on convention.
 *  The "last moment before it reaches the horizon" corresponds to the smallest angle t > 0
 *  for which some building still blocks the direct segment from the sun center to the origin-side
 *  ground; equivalently, the upper envelope of building sight angles.
 *
 *  For a rectangle [l, r] × [0, h], the limiting angle on the descending side is achieved by
 *  the top-right corner (r, h): the sun is blocked while its ray to the horizon is below that corner.
 *  This gives threshold angle atan2(h, r). The last blocked moment is the maximum of these angles.
 *
 *  Since the original full statement/input format is missing, this implementation supports the
 *  common format:
 *
 *      R N
 *      l1 r1 h1
 *      ...
 *      lN rN hN
 *      ...
 *      0 0
 *
 *  and prints the angle in radians with 10 digits after decimal point.
 *
 *  If your judge uses a different exact format, only the parser/output formatting may need adjustment.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first;
        StringBuilder out = new StringBuilder();

        while ((first = fs.next()) != null) {
            double R = Double.parseDouble(first);
            int n = Integer.parseInt(fs.next());

            if (R == 0 && n == 0) break;

            double ans = 0.0;
            for (int i = 0; i < n; i++) {
                double l = fs.nextDouble();
                double r = fs.nextDouble();
                double h = fs.nextDouble();

                if (r > 0 && h > 0) {
                    ans = Math.max(ans, Math.atan2(h, r));
                }
            }

            out.append(String.format(Locale.US, "%.10f%n", ans));
        }

        System.out.print(out.toString());
    }
}
